import logging, pins
from . import manual_probe
HINT_TIMEOUT = "\nIf the probe did not move far enough to trigger, then\nconsider reducing the Z axis minimum position so the probe\ncan travel further (the Z minimum position can be negative).\n"

def calc_probe_z_average(positions, method='average'):
    if method != "median":
        count = float(len(positions))
        return [sum([pos[i] for pos in positions]) / count for i in range(3)]
    z_sorted = sorted(positions, key=(lambda p: p[2]))
    middle = len(positions) // 2
    if len(positions) & 1 == 1:
        return z_sorted[middle]
    return calc_probe_z_average(z_sorted[middle - 1:middle + 1], "average")


class ProbeCommandHelper:

    def __init__(self, config, probe, query_endstop=None):
        self.printer = config.get_printer()
        self.probe = probe
        self.query_endstop = query_endstop
        self.name = config.get_name()
        gcode = self.printer.lookup_object("gcode")
        self.last_state = False
        self.last_z_result = 0.0
        self.probe_calibrate_z = 0.0
        if config.has_section("creality_multi_probe"):
            gcode.register_mux_command("QUERY_PROBE", "NAME", (self.name), (self.cmd_QUERY_PROBE), desc=(self.cmd_QUERY_PROBE_help))
            gcode.register_mux_command("PROBE", "NAME", (self.name), (self.cmd_PROBE), desc=(self.cmd_PROBE_help))
            gcode.register_mux_command("PROBE_CALIBRATE", "NAME", (self.name), (self.cmd_PROBE_CALIBRATE), desc=(self.cmd_PROBE_CALIBRATE_help))
            gcode.register_mux_command("PROBE_ACCURACY", "NAME", (self.name), (self.cmd_PROBE_ACCURACY), desc=(self.cmd_PROBE_ACCURACY_help))
            gcode.register_mux_command("Z_OFFSET_APPLY_PROBE", "NAME", (self.name), (self.cmd_Z_OFFSET_APPLY_PROBE),
              desc=(self.cmd_Z_OFFSET_APPLY_PROBE_help))
        else:
            gcode.register_command("QUERY_PROBE", (self.cmd_QUERY_PROBE), desc=(self.cmd_QUERY_PROBE_help))
            gcode.register_command("PROBE", (self.cmd_PROBE), desc=(self.cmd_PROBE_help))
            gcode.register_command("PROBE_CALIBRATE", (self.cmd_PROBE_CALIBRATE), desc=(self.cmd_PROBE_CALIBRATE_help))
            gcode.register_command("PROBE_ACCURACY", (self.cmd_PROBE_ACCURACY), desc=(self.cmd_PROBE_ACCURACY_help))
            gcode.register_command("Z_OFFSET_APPLY_PROBE", (self.cmd_Z_OFFSET_APPLY_PROBE),
              desc=(self.cmd_Z_OFFSET_APPLY_PROBE_help))

    def _move(self, coord, speed):
        self.printer.lookup_object("toolhead").manual_move(coord, speed)

    def get_status(self, eventtime):
        return {'name':self.name, 
         'last_query':self.last_state, 
         'last_z_result':self.last_z_result}

    cmd_QUERY_PROBE_help = "Return the status of the z-probe"

    def cmd_QUERY_PROBE(self, gcmd):
        if self.query_endstop is None:
            raise gcmd.error("Probe does not support QUERY_PROBE")
        toolhead = self.printer.lookup_object("toolhead")
        print_time = toolhead.get_last_move_time()
        res = self.query_endstop(print_time)
        self.last_state = res
        gcmd.respond_info("probe: %s" % (["open", "TRIGGERED"][not not res],))

    cmd_PROBE_help = "Probe Z-height at current XY position"

    def cmd_PROBE(self, gcmd):
        pos = run_single_probe(self.probe, gcmd)
        gcmd.respond_info("Result is z=%.6f" % (pos[2],))
        self.last_z_result = pos[2]

    def probe_calibrate_finalize(self, kin_pos):
        if kin_pos is None:
            return
        z_offset = self.probe_calibrate_z - kin_pos[2]
        gcode = self.printer.lookup_object("gcode")
        gcode.respond_info("%s: z_offset: %.3f\nThe SAVE_CONFIG command will update the printer config file\nwith the above and restart the printer." % (
         self.name, z_offset))
        configfile = self.printer.lookup_object("configfile")
        configfile.set(self.name, "z_offset", "%.3f" % (z_offset,))

    cmd_PROBE_CALIBRATE_help = "Calibrate the probe's z_offset"

    def cmd_PROBE_CALIBRATE(self, gcmd):
        manual_probe.verify_no_manual_probe(self.printer)
        params = self.probe.get_probe_params(gcmd)
        curpos = run_single_probe(self.probe, gcmd)
        self.probe_calibrate_z = curpos[2]
        curpos[2] += 5.0
        self._move(curpos, params["lift_speed"])
        (x_offset, y_offset, z_offset) = self.probe.get_offsets()
        curpos[0] += x_offset
        curpos[1] += y_offset
        self._move(curpos, params["probe_speed"])
        manual_probe.ManualProbeHelper(self.printer, gcmd, self.probe_calibrate_finalize)

    cmd_PROBE_ACCURACY_help = "Probe Z-height accuracy at current XY position"

    def cmd_PROBE_ACCURACY(self, gcmd):
        params = self.probe.get_probe_params(gcmd)
        sample_count = gcmd.get_int("SAMPLES", 10, minval=1)
        toolhead = self.printer.lookup_object("toolhead")
        pos = toolhead.get_position()
        gcmd.respond_info("PROBE_ACCURACY at X:%.3f Y:%.3f Z:%.3f (samples=%d retract=%.3f speed=%.1f lift_speed=%.1f)\n" % (
         pos[0], pos[1], pos[2],
         sample_count, params["sample_retract_dist"],
         params["probe_speed"], params["lift_speed"]))
        fo_params = dict(gcmd.get_command_parameters())
        fo_params["SAMPLES"] = "1"
        gcode = self.printer.lookup_object("gcode")
        fo_gcmd = gcode.create_gcode_command("", "", fo_params)
        probe_session = self.probe.start_probe_session(fo_gcmd)
        probe_num = 0
        while probe_num < sample_count:
            probe_session.run_probe(fo_gcmd)
            probe_num += 1
            pos = toolhead.get_position()
            liftpos = [None, None, pos[2] + params["sample_retract_dist"]]
            self._move(liftpos, params["lift_speed"])

        positions = probe_session.pull_probed_results()
        probe_session.end_probe_session()
        max_value = max([p[2] for p in positions])
        min_value = min([p[2] for p in positions])
        range_value = max_value - min_value
        avg_value = calc_probe_z_average(positions, "average")[2]
        median = calc_probe_z_average(positions, "median")[2]
        deviation_sum = 0
        for i in range(len(positions)):
            deviation_sum += pow(positions[i][2] - avg_value, 2.0)

        sigma = (deviation_sum / len(positions)) ** 0.5
        gcmd.respond_info("probe accuracy results: maximum %.6f, minimum %.6f, range %.6f, average %.6f, median %.6f, standard deviation %.6f" % (
         max_value, min_value, range_value, avg_value, median, sigma))

    cmd_Z_OFFSET_APPLY_PROBE_help = "Adjust the probe's z_offset"

    def cmd_Z_OFFSET_APPLY_PROBE(self, gcmd):
        gcode_move = self.printer.lookup_object("gcode_move")
        offset = gcode_move.get_status()["homing_origin"].z
        if offset == 0:
            gcmd.respond_info("Nothing to do: Z Offset is 0")
            return
        z_offset = self.probe.get_offsets()[2]
        new_calibrate = z_offset - offset
        gcmd.respond_info("%s: z_offset: %.3f\nThe SAVE_CONFIG command will update the printer config file\nwith the above and restart the printer." % (
         self.name, new_calibrate))
        configfile = self.printer.lookup_object("configfile")
        configfile.set(self.name, "z_offset", "%.3f" % (new_calibrate,))


class HomingViaProbeHelper:

    def __init__(self, config, mcu_probe):
        self.printer = config.get_printer()
        self.mcu_probe = mcu_probe
        self.multi_probe_pending = False
        self.name = config.get_name()
        self.pins = self.printer.lookup_object("pins")
        self.pins.register_chip(self.name, self)
        if self.pins.lookup_chip("probe") is None:
            self.pins.register_chip("probe", self)
        self.printer.register_event_handler("klippy:mcu_identify", self._handle_mcu_identify)
        self.printer.register_event_handler("homing:homing_move_begin", self._handle_homing_move_begin)
        self.printer.register_event_handler("homing:homing_move_end", self._handle_homing_move_end)
        self.printer.register_event_handler("homing:home_rails_begin", self._handle_home_rails_begin)
        self.printer.register_event_handler("homing:home_rails_end", self._handle_home_rails_end)
        self.printer.register_event_handler("gcode:command_error", self._handle_command_error)

    def _handle_mcu_identify(self):
        kin = self.printer.lookup_object("toolhead").get_kinematics()
        for stepper in kin.get_steppers():
            if stepper.is_active_axis("z"):
                self.mcu_probe.add_stepper(stepper)

    def _handle_homing_move_begin(self, hmove):
        if self.mcu_probe in hmove.get_mcu_endstops():
            self.mcu_probe.probe_prepare(hmove)

    def _handle_homing_move_end(self, hmove):
        if self.mcu_probe in hmove.get_mcu_endstops():
            self.mcu_probe.probe_finish(hmove)

    def _handle_home_rails_begin(self, homing_state, rails):
        endstops = [es for rail in rails for es, name in iter((rail.get_endstops()))]
        if self.mcu_probe in endstops:
            self.mcu_probe.multi_probe_begin()
            self.multi_probe_pending = True

    def _handle_home_rails_end(self, homing_state, rails):
        endstops = [es for rail in rails for es, name in iter((rail.get_endstops()))]
        if self.multi_probe_pending:
            if self.mcu_probe in endstops:
                self.multi_probe_pending = False
                self.mcu_probe.multi_probe_end()

    def _handle_command_error(self):
        if self.multi_probe_pending:
            self.multi_probe_pending = False
            try:
                self.mcu_probe.multi_probe_end()
            except:
                logging.exception("Homing multi-probe end")

    def setup_pin(self, pin_type, pin_params):
        if pin_type != "endstop" or pin_params["pin"] != "z_virtual_endstop":
            raise pins.error("Probe virtual endstop only useful as endstop pin")
        if pin_params["invert"] or pin_params["pullup"]:
            raise pins.error("Can not pullup/invert probe virtual endstop")
        return self.mcu_probe


class ProbeSessionHelper:

    def __init__(self, config, mcu_probe):
        self.printer = config.get_printer()
        self.mcu_probe = mcu_probe
        gcode = self.printer.lookup_object("gcode")
        self.dummy_gcode_cmd = gcode.create_gcode_command("", "", {})
        if config.has_section("stepper_z"):
            zconfig = config.getsection("stepper_z")
            self.z_position = zconfig.getfloat("position_min", 0.0, note_valid=False)
        else:
            pconfig = config.getsection("printer")
            self.z_position = pconfig.getfloat("minimum_z_position", 0.0, note_valid=False)
        self.homing_helper = HomingViaProbeHelper(config, mcu_probe)
        self.speed = config.getfloat("speed", 5.0, above=0.0)
        self.lift_speed = config.getfloat("lift_speed", (self.speed), above=0.0)
        self.sample_count = config.getint("samples", 1, minval=1)
        self.sample_retract_dist = config.getfloat("sample_retract_dist", 2.0, above=0.0)
        atypes = ["median", "average"]
        self.samples_result = config.getchoice("samples_result", atypes, "average")
        self.samples_tolerance = config.getfloat("samples_tolerance", 0.1, minval=0.0)
        self.samples_retries = config.getint("samples_tolerance_retries", 0, minval=0)
        self.multi_probe_pending = False
        self.results = []
        self.printer.register_event_handler("gcode:command_error", self._handle_command_error)

    def _handle_command_error(self):
        if self.multi_probe_pending:
            try:
                self.end_probe_session()
            except:
                logging.exception("Multi-probe end")

    def _probe_state_error(self):
        raise self.printer.command_error("Internal probe error - start/end probe session mismatch")

    def start_probe_session(self, gcmd):
        if self.multi_probe_pending:
            self._probe_state_error()
        self.mcu_probe.multi_probe_begin()
        self.multi_probe_pending = True
        self.results = []
        return self

    def end_probe_session(self):
        if not self.multi_probe_pending:
            self._probe_state_error()
        self.results = []
        self.multi_probe_pending = False
        self.mcu_probe.multi_probe_end()

    def get_probe_params(self, gcmd=None):
        if gcmd is None:
            gcmd = self.dummy_gcode_cmd
        probe_speed = gcmd.get_float("PROBE_SPEED", (self.speed), above=0.0)
        lift_speed = gcmd.get_float("LIFT_SPEED", (self.lift_speed), above=0.0)
        samples = gcmd.get_int("SAMPLES", (self.sample_count), minval=1)
        sample_retract_dist = gcmd.get_float("SAMPLE_RETRACT_DIST", (self.sample_retract_dist),
          above=0.0)
        samples_tolerance = gcmd.get_float("SAMPLES_TOLERANCE", (self.samples_tolerance),
          minval=0.0)
        samples_retries = gcmd.get_int("SAMPLES_TOLERANCE_RETRIES", (self.samples_retries),
          minval=0)
        samples_result = gcmd.get("SAMPLES_RESULT", self.samples_result)
        return {
          'probe_speed': probe_speed,
          'lift_speed': lift_speed,
          'samples': samples,
          'sample_retract_dist': sample_retract_dist,
          'samples_tolerance': samples_tolerance,
          'samples_tolerance_retries': samples_retries,
          'samples_result': samples_result}

    def _probe(self, speed):
        toolhead = self.printer.lookup_object("toolhead")
        curtime = self.printer.get_reactor().monotonic()
        if "z" not in toolhead.get_status(curtime)["homed_axes"]:
            raise self.printer.command_error("Must home before probe")
        pos = toolhead.get_position()
        pos[2] = self.z_position
        try:
            epos = self.mcu_probe.probing_move(pos, speed)
        except self.printer.command_error as e:
            try:
                reason = str(e)
                if "Timeout during endstop homing" in reason:
                    reason += HINT_TIMEOUT
                raise self.printer.command_error(reason)
            finally:
                e = None
                del e

        else:
            self.printer.send_event("probe:update_results", epos)
            gcode = self.printer.lookup_object("gcode")
            gcode.respond_info(("probe at %.3f,%.3f is z=%.6f" % (
             epos[0], epos[1], epos[2])),
              log=False)
            return epos[:3]

    def run_probe(self, gcmd):
        if not self.multi_probe_pending:
            self._probe_state_error()
        params = self.get_probe_params(gcmd)
        toolhead = self.printer.lookup_object("toolhead")
        gcode = self.printer.lookup_object("gcode")
        probexy = toolhead.get_position()[:2]
        retries = 0
        positions = []
        sample_count = params["samples"]
        while True:
            if not len(positions) < sample_count:
                if gcode.is_mcu_stop():
                    raise gcmd.error("Manual Stop")
                else:
                    pos = self._probe(params["probe_speed"])
                    positions.append(pos)
                    z_positions = [p[2] for p in positions]
                    if max(z_positions) - min(z_positions) > params["samples_tolerance"]:
                        if retries >= params["samples_tolerance_retries"]:
                            raise gcmd.error("Probe samples exceed samples_tolerance")
                        gcmd.respond_info("Probe samples exceed tolerance. Retrying...")
                        retries += 1
                        positions = []
                    if gcode.is_mcu_stop():
                        raise gcmd.error("Manual Stop")
                if len(positions) < sample_count:
                    toolhead.manual_move(probexy + [pos[2] + params["sample_retract_dist"]], params["lift_speed"])

        epos = calc_probe_z_average(positions, params["samples_result"])
        self.results.append(epos)

    def pull_probed_results(self):
        res = self.results
        self.results = []
        return res

    def change_probe_distance(self, distance):
        self.z_position = distance


class ProbeOffsetsHelper:

    def __init__(self, config):
        self.x_offset = config.getfloat("x_offset", 0.0)
        self.y_offset = config.getfloat("y_offset", 0.0)
        self.z_offset = config.getfloat("z_offset")

    def get_offsets(self):
        return (
         self.x_offset, self.y_offset, self.z_offset)


class ProbePointsHelper:

    def __init__(self, config, finalize_callback, default_points=None):
        self.printer = config.get_printer()
        self.finalize_callback = finalize_callback
        self.probe_points = default_points
        self.name = config.get_name()
        self.config = config
        self.gcode = self.printer.lookup_object("gcode")
        if default_points is None or config.get("points", None) is not None:
            self.probe_points = config.getlists("points", seps=(',', '\n'), parser=float,
              count=2)
        def_move_z = config.getfloat("horizontal_move_z", 5.0)
        self.default_horizontal_move_z = def_move_z
        self.speed = config.getfloat("speed", 50.0, above=0.0)
        self.use_offsets = False
        self.lift_speed = self.speed
        self.probe_offsets = (0.0, 0.0, 0.0)
        self.manual_results = []

    def minimum_points(self, n):
        if len(self.probe_points) < n:
            raise self.printer.config_error("Need at least %d probe points for %s" % (n, self.name))

    def update_probe_points(self, points, min_points):
        self.probe_points = points
        self.minimum_points(min_points)

    def use_xy_offsets(self, use_offsets):
        self.use_offsets = use_offsets

    def get_lift_speed(self):
        return self.lift_speed

    def _move(self, coord, speed):
        self.printer.lookup_object("toolhead").manual_move(coord, speed)

    def _raise_tool(self, is_first=False):
        speed = self.lift_speed
        if is_first:
            speed = self.speed
        self._move([None, None, self.horizontal_move_z], speed)

    def _invoke_callback(self, results):
        toolhead = self.printer.lookup_object("toolhead")
        toolhead.get_last_move_time()
        res = self.finalize_callback(self.probe_offsets, results)
        return res != "retry"

    def _move_next(self, probe_num):
        nextpos = list(self.probe_points[probe_num])
        if self.use_offsets:
            nextpos[0] -= self.probe_offsets[0]
            nextpos[1] -= self.probe_offsets[1]
        self._move(nextpos, self.speed)

    def is_mcu_stop(self):
        return self.gcode.is_mcu_stop()

    def start_manual_probe(self):
        self.lift_speed = self.speed
        self.probe_offsets = (0.0, 0.0, 0.0)
        self.manual_results = []
        self._manual_probe_start()

    def start_current_probe(self, gcmd):
        multi_prober = self.printer.lookup_object("creality_multi_probe")
        if multi_prober.get_scan_probe_name() == "creality_probe_current":
            multi_prober.set_run_probe(multi_prober.get_scan_probe_name())
            from . import creality_probe_current
            scan_helper = creality_probe_current.ProbeScanHelper(self, self.printer, self.probe_points, self.use_offsets, self.speed, self.horizontal_move_z, self.finalize_callback)
            error = ""
            try:
                scan_helper.perform_scan(gcmd)
            except creality_probe_current.ScanStopEndSignal as e:
                try:
                    pass
                finally:
                    e = None
                    del e

            except gcmd.error as e:
                try:
                    error = str(e)
                finally:
                    e = None
                    del e

            else:
                multi_prober.set_run_probe(multi_prober.get_main_probe_name())
                if error != "":
                    raise gcmd.error(error)

    def start_automatic_probe(self, gcmd):
        probe = self.printer.lookup_object("probe", None)
        self.lift_speed = probe.get_probe_params(gcmd)["lift_speed"]
        self.probe_offsets = probe.get_offsets()
        if self.horizontal_move_z < self.probe_offsets[2]:
            raise gcmd.error("horizontal_move_z can't be less than probe's z_offset")
        probe_session = probe.start_probe_session(gcmd)
        probe_num = 0
        while True:
            if self.is_mcu_stop():
                break
            else:
                self._raise_tool(not probe_num)
                if probe_num >= len(self.probe_points):
                    results = probe_session.pull_probed_results()
                    done = self._invoke_callback(results)
                    if done:
                        break
                    probe_num = 0
                if self.is_mcu_stop():
                    break
                self._move_next(probe_num)
                if self.is_mcu_stop():
                    break
                probe_session.run_probe(gcmd)
                probe_num += 1

        probe_session.end_probe_session()

    def start_probe(self, gcmd, is_mesh=False):
        manual_probe.verify_no_manual_probe(self.printer)
        probe = self.printer.lookup_object("probe", None)
        method = gcmd.get("METHOD", "automatic").lower()
        def_move_z = self.default_horizontal_move_z
        self.horizontal_move_z = gcmd.get_float("HORIZONTAL_MOVE_Z", def_move_z)
        if probe is None or method == "manual":
            return self.start_manual_probe()
        if is_mesh:
            if self.config.has_section("creality_multi_probe"):
                return self.start_current_probe(gcmd)
            return self.start_automatic_probe(gcmd)

    def _manual_probe_start(self):
        self._raise_tool(not self.manual_results)
        gcmd = self.gcode.create_gcode_command("", "", {})
        if len(self.manual_results) >= len(self.probe_points):
            done = self._invoke_callback(self.manual_results)
            if done:
                return
            self.manual_results = []
        self._move_next(len(self.manual_results))
        manual_probe.ManualProbeHelper(self.printer, gcmd, self._manual_probe_finalize)

    def _manual_probe_finalize(self, kin_pos):
        if kin_pos is None:
            return
        self.manual_results.append(kin_pos)
        self._manual_probe_start()


def run_single_probe(probe, gcmd):
    probe_session = probe.start_probe_session(gcmd)
    probe_session.run_probe(gcmd)
    pos = probe_session.pull_probed_results()[0]
    probe_session.end_probe_session()
    return pos


class ProbeEndstopWrapper:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.position_endstop = config.getfloat("z_offset")
        self.stow_on_each_sample = config.getboolean("deactivate_on_each_sample", True)
        gcode_macro = self.printer.load_object(config, "gcode_macro")
        self.activate_gcode = gcode_macro.load_template(config, "activate_gcode", "")
        self.deactivate_gcode = gcode_macro.load_template(config, "deactivate_gcode", "")
        ppins = self.printer.lookup_object("pins")
        self.mcu_endstop = ppins.setup_pin("endstop", config.get("pin"))
        self.get_mcu = self.mcu_endstop.get_mcu
        self.add_stepper = self.mcu_endstop.add_stepper
        self.get_steppers = self.mcu_endstop.get_steppers
        self.home_start = self.mcu_endstop.home_start
        self.home_wait = self.mcu_endstop.home_wait
        self.query_endstop = self.mcu_endstop.query_endstop
        self.multi = "OFF"

    def _raise_probe(self):
        toolhead = self.printer.lookup_object("toolhead")
        start_pos = toolhead.get_position()
        self.deactivate_gcode.run_gcode_from_command()
        if toolhead.get_position()[:3] != start_pos[:3]:
            raise self.printer.command_error("Toolhead moved during probe deactivate_gcode script")

    def _lower_probe(self):
        toolhead = self.printer.lookup_object("toolhead")
        start_pos = toolhead.get_position()
        self.activate_gcode.run_gcode_from_command()
        if toolhead.get_position()[:3] != start_pos[:3]:
            raise self.printer.command_error("Toolhead moved during probe activate_gcode script")

    def multi_probe_begin(self):
        if self.stow_on_each_sample:
            return
        self.multi = "FIRST"

    def multi_probe_end(self):
        if self.stow_on_each_sample:
            return
        self._raise_probe()
        self.multi = "OFF"

    def probing_move(self, pos, speed):
        phoming = self.printer.lookup_object("homing")
        return phoming.probing_move(self, pos, speed)

    def probe_prepare(self, hmove):
        if self.multi == "OFF" or self.multi == "FIRST":
            self._lower_probe()
            if self.multi == "FIRST":
                self.multi = "ON"

    def probe_finish(self, hmove):
        if self.multi == "OFF":
            self._raise_probe()

    def get_position_endstop(self):
        return self.position_endstop


class PrinterProbe:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.mcu_probe = ProbeEndstopWrapper(config)
        self.cmd_helper = ProbeCommandHelper(config, self, self.mcu_probe.query_endstop)
        self.probe_offsets = ProbeOffsetsHelper(config)
        self.probe_session = ProbeSessionHelper(config, self.mcu_probe)

    def get_probe_params(self, gcmd=None):
        return self.probe_session.get_probe_params(gcmd)

    def get_offsets(self):
        return self.probe_offsets.get_offsets()

    def get_status(self, eventtime):
        return self.cmd_helper.get_status(eventtime)

    def start_probe_session(self, gcmd):
        return self.probe_session.start_probe_session(gcmd)


def load_config(config):
    return PrinterProbe(config)

